export const HexToRGB=t=>{let e=0,r=0,o=0;return 4===t.length?(e=`0x${t[1]}${t[1]}`,r=`0x${t[2]}${t[2]}`,o=`0x${t[3]}${t[3]}`):7===t.length&&(e=`0x${t[1]}${t[2]}`,r=`0x${t[3]}${t[4]}`,o=`0x${t[5]}${t[6]}`),[e,r,o]};export const HexToHSL=t=>{const e=HexToRGB(t);let r=e[0],o=e[1],n=e[2];r/=255,o/=255,n/=255;const a=Math.min(r,o,n),i=Math.max(r,o,n),s=i-a;let u=0,x=0,l=0;return u=0===s?0:i===r?(o-n)/s%6:i===o?(n-r)/s+2:(r-o)/s+4,u=Math.round(60*u),u<0&&(u+=360),l=(i+a)/2,x=0===s?0:s/(1-Math.abs(2*l-1)),x=+(100*x).toFixed(1),l=+(100*l).toFixed(1),[u,x,l]};export const HSLToRGB=(t,e,r)=>{const o=e/100,n=r/100,a=(1-Math.abs(2*n-1))*o,i=a*(1-Math.abs(t/60%2-1)),s=n-a/2;let u=0,x=0,l=0;return 0<=t&&t<60?(u=a,x=i,l=0):60<=t&&t<120?(u=i,x=a,l=0):120<=t&&t<180?(u=0,x=a,l=i):180<=t&&t<240?(u=0,x=i,l=a):240<=t&&t<300?(u=i,x=0,l=a):300<=t&&t<360&&(u=a,x=0,l=i),u=Math.round(255*(u+s)).toString(16),x=Math.round(255*(x+s)).toString(16),l=Math.round(255*(l+s)).toString(16),[u,x,l]};export const HSLToHex=(t,e,r)=>{const o=HSLToRGB(t,e,r);return o[0]=padZero(o[0]),o[1]=padZero(o[1]),o[2]=padZero(o[2]),`#${o[0]}${o[1]}${o[2]}`};export const invertColor=t=>{let e=t;if(0===t.indexOf("#")&&(e=t.slice(1)),3===e.length&&(e=e[0]+e[0]+e[1]+e[1]+e[2]+e[2]),6!==e.length)throw new Error("Invalid HEX color.");const r=(255-Number.parseInt(e.slice(0,2),16)).toString(16),o=(255-Number.parseInt(e.slice(2,4),16)).toString(16),n=(255-Number.parseInt(e.slice(4,6),16)).toString(16);return`#${padZero(r)}${padZero(o)}${padZero(n)}`};export const getColorForPositiveInteger=(t,e=70,r=50)=>{if(t<0||!Number.isInteger(t))throw new Error("Input must be a positive integer");if(e<0||e>100)throw new Error("Saturation must be a value between 0 and 100");if(r<0||r>100)throw new Error("Lightness must be a value between 0 and 100");return HSLToHex(137.508*t%360,e,r)};function padZero(t,e){const r=e||2;return(new Array(r).join("0")+t).slice(-r)}